    H=len(grid);W=len(grid[0]);g=[r[:] for r in grid];seen=set()
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    y,x=st.pop();cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<H and 0<=b<W and g[a][b] and (a,b) not in seen:
                                seen.add((a,b));st.append((a,b))
                ys=[p[0] for p in cells];xs=[p[1] for p in cells]
                h=max(ys)-min(ys)+1;w=max(xs)-min(xs)+1
                if h<3 or w<3:
                    for y,x in cells:g[y][x]=0
    return g
